import CodePlugin from "./code-plugin"

export default function Page() {
  return <CodePlugin />
}

"use client"

import { useCodeAnimation } from "./hooks/use-code-animation"
import { CODE_CONTENT } from "./lib/config"

import "./styles/code-plugin.css"

export default function CodePlugin() {
  const { charIdx, phase, scrollRef } = useCodeAnimation()
  const visible = CODE_CONTENT.slice(0, charIdx)
  const isTyping = phase === "typing"

  return (
    <div className="cp-root relative w-full overflow-hidden" style={{ height: "18rem" }}>
      <div
        ref={scrollRef}
        className="cp-body h-full overflow-y-auto px-2 pb-16 pt-4"
        style={{ scrollbarWidth: "none" }}
      >
        <pre className="cp-text m-0 whitespace-pre font-mono text-[13px] leading-relaxed">
          {visible}
          {isTyping && <span className="cp-cursor" />}
        </pre>
      </div>
    </div>
  )
}

// Phase flow: idle → typing → done → idle (loops)
import { useEffect, useRef, useState } from "react"

import {
  CODE_CONTENT,
  DONE_PAUSE_MS,
  IDLE_PAUSE_MS,
  TYPE_CHAR_MS,
  TYPE_NEWLINE_MS,
  type Phase,
} from "../lib/config"

export function useCodeAnimation() {
  const [charIdx, setCharIdx] = useState(0)
  const [phase, setPhase] = useState<Phase>("idle")
  const scrollRef = useRef<HTMLDivElement>(null)

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight
    }
  }, [charIdx])

  useEffect(() => {
    if (phase !== "idle") return
    const t = setTimeout(() => setPhase("typing"), IDLE_PAUSE_MS)
    return () => clearTimeout(t)
  }, [phase])

  useEffect(() => {
    if (phase !== "typing") return
    if (charIdx >= CODE_CONTENT.length) {
      const t = setTimeout(() => setPhase("done"), DONE_PAUSE_MS)
      return () => clearTimeout(t)
    }
    const ch = CODE_CONTENT[charIdx]
    const delay = ch === "\n" ? TYPE_NEWLINE_MS : TYPE_CHAR_MS
    const t = setTimeout(() => setCharIdx((i) => i + 1), delay)
    return () => clearTimeout(t)
  }, [phase, charIdx])

  useEffect(() => {
    if (phase !== "done") return
    const t = setTimeout(() => {
      setCharIdx(0)
      setPhase("idle")
    }, 600)
    return () => clearTimeout(t)
  }, [phase])

  return { charIdx, phase, scrollRef }
}

export type Phase = "idle" | "typing" | "done"

export const TYPE_CHAR_MS = 16
export const TYPE_NEWLINE_MS = 38
export const DONE_PAUSE_MS = 2800
export const IDLE_PAUSE_MS = 500

