/* code-plugin — frameless JSON typing animation with edge fade */

.cp-root {
  --cp-text-color: #71717a;
  --cp-cursor-color: #a1a1aa;
}

.dark .cp-root {
  --cp-text-color: #a1a1aa;
  --cp-cursor-color: #71717a;
}

.cp-root {
  -webkit-mask-image: linear-gradient(
    to bottom,
    transparent 0%,
    black 22%,
    black 78%,
    transparent 100%
  );
  mask-image: linear-gradient(
    to bottom,
    transparent 0%,
    black 22%,
    black 78%,
    transparent 100%
  );
}

.cp-body::-webkit-scrollbar {
  display: none;
}

.cp-text {
  color: var(--cp-text-color);
}

.cp-cursor {
  display: inline-block;
  width: 6px;
  height: 1em;
  margin-left: 1px;
  vertical-align: text-bottom;
  background-color: var(--cp-cursor-color);
  animation: cp-blink 1.15s step-start infinite;
}

@keyframes cp-blink {
  0%,
  49.9% {
    opacity: 1;
  }
  50%,
  100% {
    opacity: 0;
  }
}
